import os
import torch


class Config:
    """
    Global configuration for the Artwork Attribute Labeling task.
    Implements settings for a Heterogeneous Ensemble (ConvNeXt + Swin Transformer).
    """

    # --- General ---
    seed = 42
    debug = False  # Set to True to run on a small subset for debugging

    # --- Data Paths ---
    input_dir = "./input"
    # Metadata files generated by the provided metadata script
    train_metadata_path = "./metadata/train_metadata.csv"
    val_metadata_path = "./metadata/val_metadata.csv"
    test_metadata_path = "./metadata/test_metadata.csv"

    # --- Data Parameters ---
    num_classes = 3474
    image_size = 384

    # --- Model Architecture ---
    # Heterogeneous Ensemble:
    # 1. ConvNeXt Small: Strong CNN baseline, good for texture/local features.
    # 2. Swin Transformer Small: Hierarchical Transformer, good for global context/scenic images.
    model_names = [
        "convnext_small.fb_in22k_ft_in1k_384",
        "swin_base_patch4_window12_384.ms_in22k_ft_in1k",
    ]

    # --- Training Hyperparameters ---
    epochs = 8
    batch_size = 32  # Fits on A100-40GB with 384x384 images
    num_workers = 10  # Optimized for 12 vCPUs

    # Optimizer (AdamW)
    lr = 2e-4
    weight_decay = 0.01

    # Scheduler (OneCycleLR)
    pct_start = 0.1
    div_factor = 25.0
    final_div_factor = 1000.0

    # Loss Function (Asymmetric Loss)
    # Addresses high class imbalance and label noise
    asl_gamma_neg = 4.0
    asl_gamma_pos = 0.0
    asl_clip = 0.05

    # Exponential Moving Average (EMA)
    # Stabilizes training against noisy labels
    use_ema = True
    ema_decay = 0.9998

    # --- Inference ---
    use_tta = True  # Use Test-Time Augmentation (Horizontal Flip)

    # --- Directories ---
    working_dir = "./working/idea_3"
    submission_dir = "./submission"
    submission_path = os.path.join(submission_dir, "submission.csv")

    # --- Hardware ---
    device = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Initialize necessary directories.
        """
        os.makedirs(cls.working_dir, exist_ok=True)
        os.makedirs(cls.submission_dir, exist_ok=True)


# Automatically setup directories when config is imported
Config.setup()
